import itertools
from collections import Counter

def get_diffs(block):
    diffs = []
    for a, b in itertools.combinations(block, 2):
        d1 = (a - b) % 13
        d2 = (b - a) % 13
        diffs.extend([d1, d2])
    return diffs

def search_base_blocks():
    all_triples = list(itertools.combinations(range(13), 3))
    def backtrack(start, current, diff_count):
        if len(current) == 4:
            if all(count == 2 for count in diff_count.values()):
                return current
            return None
        for i in range(start, len(all_triples)):
            triple = all_triples[i]
            new_diffs = get_diffs(triple)
            if all(diff_count[d] + new_diffs.count(d) <= 2 for d in set(new_diffs)):
                for d in new_diffs:
                    diff_count[d] += 1
                res = backtrack(i + 1, current + [triple], diff_count)
                if res:
                    return res
                for d in new_diffs:
                    diff_count[d] -= 1
        return None

    diff_count = Counter()
    result = backtrack(0, [], diff_count)
    return result

result = search_base_blocks()
print(result)
